103	    /**
104	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
105	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
106	     * been assigned.
107	     */
108	    default Integer checkDigit(Owner owner) {
109	        String customerCode = owner.getCustomerCode();
110	        if (customerCode == null) {
111	            return null;
112	        }
113	        int sum = 0;
114	        boolean dbl = true;
115	        for (int i = customerCode.length() - 1; i >= 0; i--) {
116	            char c = customerCode.charAt(i);
117	            if (c < '0' || c > '9') {
118	                continue;
119	            }
120	            int d = c - '0';
121	            if (dbl) {
122	                d *= 2;
123	                if (d > 9) {
124	                    d -= 9;
125	                }
126	            }
127	            sum += d;
128	            dbl = !dbl;
129	        }
130	        return (10 - (sum % 10)) % 10;
131	    }
