157	    /**
158	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
159	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
160	     */
161	    default int membershipLevel(Owner owner) {
162	        int points = membershipPoints(owner);
163	        if (points <= 1) {
164	            return 1;
165	        }
166	        if (points <= 3) {
167	            return 2;
168	        }
169	        if (points <= 5) {
170	            return 3;
171	        }
172	        return 4;
173	    }
174	
175	    /**
176	     * The owner's tenure in whole elapsed fiscal years (fiscal years start 1 July): the number of
177	     * 1-July boundaries between its {@code registrationDate} and today, derived via
178	     * {@code FiscalYear} so it matches the fiscal year the membership number and {@code fiscalYear}
