181	     */
182	    default long tenureFiscalYears(Owner owner) {
183	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
184	        if (registrationDate == null) {
185	            return 0;
186	        }
187	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear
188	            .elapsed(registrationDate, java.time.LocalDate.now());
189	    }
190	
191	    /**
192	     * The owner's {@code fiscalYear} label, {@code FY<YY>} for the fiscal year (starting 1 July)
