194	     * {@code FiscalYear}. Returns {@code null} when no registration date is stored, so the field is
195	     * absent for such owners.
196	     */
197	    default String fiscalYear(Owner owner) {
198	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
199	        if (registrationDate == null) {
200	            return null;
201	        }
202	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
203	    }
204	
205	    /**
206	     * Derives the owner's locality (region) at read time from the region-and-hash
207	     * {@code customerCode}: its {@code REGION} prefix (e.g. {@code NSW} for {@code NSW-1A2B3C4D}),
208	     * so the region cannot drift from the identity every other derived value flows through. Owners
209	     * with no {@code customerCode} fall back to resolving the region directly. Both the parse and
210	     * the fallback (including the {@code UNKNOWN} sentinel) live in {@code OwnerCustomerCode}.
