244	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
245	        ownerPageDto.setPage(ownerPage.getNumber());
246	        ownerPageDto.setSize(ownerPage.getSize());
247	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
248	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
249	        return ownerPageDto;
